<template><article class="attention-card"><div class="attention-card-top"><span class="attention-priority"><AlertTriangle :size="16" aria-hidden="true"/>{{ priorityLabel }}</span><span v-if="item.trigger_facts?.source_status==='mock'" class="demo-label">演示数据</span><time>{{ relativeTime }}</time></div><h2>{{ item.patient }}</h2><p>{{ item.summary }}</p><dl><div><dt>触发类型</dt><dd>{{ typeLabel }}</dd></div><div><dt>状态</dt><dd>{{ statusLabel }}</dd></div><div v-if="item.assigned_to"><dt>负责人</dt><dd>{{ item.assigned_to }}</dd></div></dl><div class="attention-actions"><RouterLink class="v2-button primary" :to="`/therapist/reviews/${item.id}`">{{ item.status === 'waiting_plan_publish' ? '查看待发布方案' : '打开复核' }}</RouterLink><RouterLink class="v2-button secondary" :to="`/therapist/patients/${item.patient_user_id}`">查看患者</RouterLink><button v-if="item.status==='open'" class="v2-button secondary" @click="$emit('acknowledge', item.id)">我来处理</button></div></article></template>
<script setup lang="ts">import { computed } from 'vue';import { AlertTriangle } from 'lucide-vue-next';import type { AttentionItemV2 } from '@/api/v2';const props=defineProps<{item:AttentionItemV2}>();defineEmits<{acknowledge:[id:string]}>();const priorityLabel=computed(()=>({high:'高优先',normal:'需要关注',low:'一般'} as Record<string,string>)[props.item.priority]||'需要关注');const typeLabel=computed(()=>({patient_help_request:'患者请求帮助',repeated_comparable_difficulty:'持续困难',increasing_prompt_dependency:'提示依赖增加',repeated_ungradable_attempt:'连续无法评分',training_adherence_drop:'训练坚持度下降',assessment_due:'正式评估到期',stage_review_due:'阶段复核到期',evaluation_write_failure:'评估写入异常',data_conflict:'数据冲突',comparable_metric_decline:'趋势变化'} as Record<string,string>)[props.item.type]||props.item.type);const statusLabel=computed(()=>({open:'待接手',acknowledged:'已接手',in_review:'复核中',waiting_information:'等待补充',waiting_plan_publish:'等待方案发布'} as Record<string,string>)[props.item.status]||props.item.status);const relativeTime=computed(()=>new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(props.item.created_at)));</script>
